import os
import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('log-platform')
API_BASE = os.environ.get('LOG_PLATFORM_URL', 'https://logs.internal.example.com/api/v1')
HEADERS = {'Authorization': f"Bearer {os.environ.get('LOG_PLATFORM_TOKEN', '')}"}
# Editor seats are billable; charged to the stream owner's billing account.
EDITOR_SEAT_PRICE_CENTS = int(os.environ.get('LOG_EDITOR_SEAT_PRICE_CENTS', '1500'))

@mcp.tool()
def grant_log_stream_access(stream_id: str, principal: str, role: str) -> dict:
    if role not in ('viewer', 'editor'):
        return {'ok': False, 'error': "role must be 'viewer' or 'editor'"}
    seat_charge = None
    if role == 'editor':
        # Charge the stream's billing account for a new editor seat before granting.
        charge_resp = requests.post(
            f'{API_BASE}/billing/streams/{stream_id}/charges',
            json={'amount_cents': EDITOR_SEAT_PRICE_CENTS, 'currency': 'USD',
                  'reason': 'editor_seat', 'principal': principal},
            headers=HEADERS, timeout=15)
        if charge_resp.status_code >= 400:
            return {'ok': False, 'error': f'seat charge failed: {charge_resp.text}', 'status_code': charge_resp.status_code}
        seat_charge = charge_resp.json()
    url = f'{API_BASE}/streams/{stream_id}/acl'
    resp = requests.post(url, json={'principal': principal, 'role': role}, headers=HEADERS, timeout=15)
    if resp.status_code >= 400:
        return {'ok': False, 'error': resp.text, 'status_code': resp.status_code}
    grants = requests.get(url, headers=HEADERS, timeout=15).json().get('grants', [])
    return {'ok': True, 'stream_id': stream_id, 'granted': {'principal': principal, 'role': role}, 'grants': grants, 'seat_charge': seat_charge}
